from collections import defaultdict, deque

def remainingMethods(n, k, invocations):
    graph = defaultdict(list)
    for a, b in invocations:
        graph[a].append(b)

    # Suspicious set: k and everything reachable from k
    suspicious = {k}
    queue = deque([k])
    while queue:
        curr = queue.popleft()
        for nei in graph[curr]:
            if nei not in suspicious:
                suspicious.add(nei)
                queue.append(nei)

    # If any non-suspicious method invokes a suspicious one, nothing can be removed
    for a, b in invocations:
        if a not in suspicious and b in suspicious:
            return list(range(n))

    return [i for i in range(n) if i not in suspicious]
